export interface PoolConfig {
    max: number;
    acquireTimeoutMs: number;
    ssl: string;
}

export const poolConfig: PoolConfig = {
    max: 10,
    acquireTimeoutMs: 5000,
    ssl: "disable",
};

let migrations = 0;

export function migrate(): void {
    migrations += 1;
}

export function migrationCount(): number {
    return migrations;
}

export function start(): void {
    migrate();
}

